"use client";
import { useSearchParams } from "next/navigation";
import { useState } from "react";
import {categoriesMockData} from "@/mockdata/mockdata";
import ProductCard from "@/components/ProductCard";
import Categories from "@/components/Categories";
import ServicePromotion from "@/components/ServicePromotionFilter";
import PriceFilter from "@/components/PriceFilter";
import RatingFilter from "@/components/RatingFilter";

export default function CategoryPage() {
  const searchParams = useSearchParams();
  const id = searchParams.get("q");
  const categories = categoriesMockData.find(p => p.id === parseInt(id));
  const [sidebarOpen, setSidebarOpen] = useState(false);
  
  if (!categories) return <div>Product not found</div>;

  return (
    <div className="min-h-screen bg-gray-50">
      <div className="flex">
        {/* Mobile Menu Button */}
        <button
          onClick={() => setSidebarOpen(!sidebarOpen)}
          className="lg:hidden fixed top-4 left-4 z-50 bg-white p-2 rounded-md shadow-md"
        >
          <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6h16M4 12h16M4 18h16" />
          </svg>
        </button>

        {/* Sidebar */}
        <aside className={`
          fixed lg:sticky top-0 left-0 z-40 w-80 h-screen bg-white shadow-lg transform transition-transform duration-300 ease-in-out overflow-y-auto
          ${sidebarOpen ? 'translate-x-0' : '-translate-x-full'}
          lg:translate-x-0 lg:w-72 xl:w-80
        `}>
          {/* Close button for mobile */}
          <button
            onClick={() => setSidebarOpen(false)}
            className="lg:hidden absolute top-4 right-4 p-2 hover:bg-gray-100 rounded-full"
          >
            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
            </svg>
          </button>

          <div className="p-6 pt-16 lg:pt-6">
            {/* Category Section */}
            <div className="mb-8">
              <h2 className="text-lg font-bold text-gray-900 mb-4 border-b border-gray-200 pb-2">Category</h2>
              <Categories />
            </div>

            {/* Service & Promotion Section */}
            <div className="mb-8">
              <ServicePromotion />
            </div>

            {/* Price Filter Section */}
            <div className="mb-8">
              <PriceFilter />
            </div>

            {/* Rating Filter Section */}
            <div className="mb-8">
              <RatingFilter />
            </div>
          </div>
        </aside>

        {/* Overlay for mobile */}
        {sidebarOpen && (
          <div 
            className="fixed inset-0 bg-black bg-opacity-50 z-30 lg:hidden"
            onClick={() => setSidebarOpen(false)}
          />
        )}

        {/* Main Content */}
        <main className="flex-1 lg:ml-0">
          <div className="p-4 lg:p-6 xl:p-8 pt-16 lg:pt-6">
            
            {/* Product Grid */}
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-2 xl:grid-cols-3 2xl:grid-cols-4 gap-4 lg:gap-6 mb-8">
              {categories.products.map((category) => (
                <ProductCard
                  key={category.id}
                  id={category.id}
                  image={category.images.main}
                  title={category.name}
                  price={category.price}
                  rating={category.rating}
                  ratingCount={category.totalRatings}
                />
              ))}
            </div>

            {/* Load More Button */}
            <div className="flex justify-center mb-8">
              <button className="bg-red-500 hover:bg-red-600 text-white font-medium py-3 px-8 rounded-lg transition-colors duration-200 shadow-md hover:shadow-lg">
                Load more.....
              </button>
            </div>
          </div>
        </main>
      </div>
    </div>
  );
}